INSERT INTO `act_ge_bytearray` VALUES ('295002',1,'D:\\workproject\\springbladeandreact\\springBlade\\blade-service\\blade-workflow\\target\\classes\\processes\\simple-approval.bpmn20.xml','295001',_binary '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\"\r\n             xmlns:flowable=\"http://flowable.org/bpmn\"\r\n             targetNamespace=\"http://springblade.workflow\"\r\n             id=\"definitions_simpleApproval\">\r\n\r\n    <process id=\"simpleApproval\" name=\"Simple Approval\" isExecutable=\"true\">\r\n        <startEvent id=\"startEvent\" name=\"发起\"/>\r\n        <userTask id=\"approveTask\" name=\"审批\" flowable:assignee=\"${approver}\"/>\r\n        <endEvent id=\"endEvent\" name=\"结束\"/>\r\n\r\n        <sequenceFlow id=\"flow_start_approve\" sourceRef=\"startEvent\" targetRef=\"approveTask\"/>\r\n        <sequenceFlow id=\"flow_approve_end\" sourceRef=\"approveTask\" targetRef=\"endEvent\"/>\r\n    </process>\r\n\r\n</definitions>\r\n',0),('295003',1,'D:\\workproject\\springbladeandreact\\springBlade\\blade-service\\blade-workflow\\target\\classes\\processes\\customApprovalWorkflow.bpmn20.xml','295001',_binary '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\"\r\n             xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\r\n             xmlns:flowable=\"http://flowable.org/bpmn\"\r\n             targetNamespace=\"http://springblade.workflow\"\r\n             id=\"definitions_customApprovalWorkflow\">\r\n\r\n    <!--\r\n        自定义审批流程（customApprovalWorkflow）\r\n        ============================================================\r\n        语义约定（与需求对齐）：\r\n        1. 流程「入口」明确为【申请人填写】节点（startEvent 之后的首个 userTask）；\r\n           流程「出口」明确为【归档】节点（endEvent）。\r\n        2. 相邻节点之间的连线同时具备两种能力：\r\n             · 继续向下流转（forward）：审批通过时流转到下一节点；\r\n             · 驳回上一节点（reject）：审批不通过时回退到上一节点重新处理。\r\n           由各审批节点完成时写入的流程变量 outcome（approve / reject）驱动条件连线。\r\n        3. 每个审批节点的「向下连线」设为 default，保证 outcome 缺省/异常时安全向下；\r\n           「驳回连线」为条件连线（outcome == \'reject\'），指向其上一节点。\r\n        4. 申请人填写为首个节点，无「上一节点」，故只有向下连线；归档为终态 endEvent。\r\n        5. assignee 表达式（${applicant} / ${supervisor} / ${deptApprover}）为占位，\r\n           实际由项目 WfOperatorResolver 在发起/推进时按组织数据解析并写入流程变量。\r\n    -->\r\n\r\n    <process id=\"customApprovalWorkflow\" name=\"自定义审批流程\" isExecutable=\"true\">\r\n\r\n        <!-- 流程开始 -->\r\n        <startEvent id=\"startEvent\" name=\"开始\"/>\r\n\r\n        <!-- ① 申请人填写（流程入口节点） -->\r\n        <userTask id=\"fillTask\" name=\"申请人填写\" flowable:assignee=\"${applicant}\">\r\n            <documentation>流程入口：申请人填写表单并提交，随后流转至主管审批。作为首个节点无驳回目标。</documentation>\r\n        </userTask>\r\n\r\n        <!-- ② 主管审批 -->\r\n        <userTask id=\"supervisorApprove\" name=\"主管审批\" flowable:assignee=\"${supervisor}\"\r\n                  default=\"flow_supervisor_dept\">\r\n            <documentation>审批通过→流转至部门审批；驳回→回退至申请人填写重新提交。</documentation>\r\n        </userTask>\r\n\r\n        <!-- ③ 部门审批 -->\r\n        <userTask id=\"deptApprove\" name=\"部门审批\" flowable:assignee=\"${deptApprover}\"\r\n                  default=\"flow_dept_archive\">\r\n            <documentation>审批通过→流转至归档；驳回→回退至主管审批重新审批。</documentation>\r\n        </userTask>\r\n\r\n        <!-- 流程归档（流程出口节点） -->\r\n        <endEvent id=\"archiveEnd\" name=\"归档\"/>\r\n\r\n        <!-- ============ 相邻节点连线：向下流转 + 驳回上一节点 ============ -->\r\n\r\n        <!-- 开始 → 申请人填写 -->\r\n        <sequenceFlow id=\"flow_start_fill\" sourceRef=\"startEvent\" targetRef=\"fillTask\"/>\r\n\r\n        <!-- 申请人填写 → 主管审批（首个节点，仅向下，无条件） -->\r\n        <sequenceFlow id=\"flow_fill_supervisor\" sourceRef=\"fillTask\" targetRef=\"supervisorApprove\"/>\r\n\r\n        <!-- 主管审批 → 部门审批（向下流转，default） -->\r\n        <sequenceFlow id=\"flow_supervisor_dept\" sourceRef=\"supervisorApprove\" targetRef=\"deptApprove\">\r\n            <conditionExpression xsi:type=\"tFormalExpression\"><![CDATA[${outcome == \'approve\'}]]></conditionExpression>\r\n        </sequenceFlow>\r\n        <!-- 主管审批 → 申请人填写（驳回上一节点） -->\r\n        <sequenceFlow id=\"flow_supervisor_reject_fill\" sourceRef=\"supervisorApprove\" targetRef=\"fillTask\">\r\n            <conditionExpression xsi:type=\"tFormalExpression\"><![CDATA[${outcome == \'reject\'}]]></conditionExpression>\r\n        </sequenceFlow>\r\n\r\n        <!-- 部门审批 → 归档（向下流转，default） -->\r\n        <sequenceFlow id=\"flow_dept_archive\" sourceRef=\"deptApprove\" targetRef=\"archiveEnd\">\r\n            <conditionExpression xsi:type=\"tFormalExpression\"><![CDATA[${outcome == \'approve\'}]]></conditionExpression>\r\n        </sequenceFlow>\r\n        <!-- 部门审批 → 主管审批（驳回上一节点） -->\r\n        <sequenceFlow id=\"flow_dept_reject_supervisor\" sourceRef=\"deptApprove\" targetRef=\"supervisorApprove\">\r\n            <conditionExpression xsi:type=\"tFormalExpression\"><![CDATA[${outcome == \'reject\'}]]></conditionExpression>\r\n        </sequenceFlow>\r\n\r\n    </process>\r\n\r\n</definitions>\r\n',0),('297502',1,'newmodel_verify_20261006.bpmn20.xml','297501',_binary '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\" xmlns:flowable=\"http://flowable.org/bpmn\" xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\" xmlns:omgdc=\"http://www.omg.org/spec/DD/20100524/DC\" xmlns:omgdi=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:bpmn=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" typeLanguage=\"http://www.w3.org/2001/XMLSchema\" expressionLanguage=\"http://www.w3.org/1999/XPath\" targetNamespace=\"http://bpmn.io/schema/bpmn\" id=\"Definitions_newmodel_verify_20261006\">\n  <process id=\"newmodel_verify_20261006\" name=\"新模型验证流程-创建节点UserTask\" isExecutable=\"true\">\n    <startEvent id=\"StartEvent_1\" name=\"开始\"></startEvent>\n    <sequenceFlow id=\"Flow_1\" sourceRef=\"StartEvent_1\" targetRef=\"UserTask_1\"></sequenceFlow>\n    <userTask id=\"UserTask_1\" name=\"创建\">\n      <extensionElements>\n        <wf:node xmlns:wf=\"http://www.springblade.org/workflow\" nodeType=\"0\" sortOrder=\"1\" allowReject=\"1\" allowForward=\"1\">\n          <wf:operator opType=\"17\" groupNo=\"1\" signOrder=\"0\"></wf:operator>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"Flow_2\" sourceRef=\"UserTask_1\" targetRef=\"UserTask_2\"></sequenceFlow>\n    <userTask id=\"UserTask_2\" name=\"经理审批\" flowable:assignee=\"${wfMiAssignee}\">\n      <extensionElements>\n        <wf:node xmlns:wf=\"http://www.springblade.org/workflow\" nodeType=\"1\" sortOrder=\"2\" allowReject=\"1\" allowForward=\"1\">\n          <wf:operator opType=\"3\" groupNo=\"1\" objId=\"1123598821738675201\" signOrder=\"0\"></wf:operator>\n        </wf:node>\n      </extensionElements>\n      <multiInstanceLoopCharacteristics isSequential=\"false\" flowable:collection=\"wfMiAssignees_UserTask_2\" flowable:elementVariable=\"wfMiAssignee\">\n        <completionCondition>${nrOfCompletedInstances &gt;= 1}</completionCondition>\n      </multiInstanceLoopCharacteristics>\n    </userTask>\n    <sequenceFlow id=\"Flow_3\" sourceRef=\"UserTask_2\" targetRef=\"EndEvent_1\"></sequenceFlow>\n    <endEvent id=\"EndEvent_1\" name=\"结束\"></endEvent>\n  </process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_newmodel_verify_20261006\">\n    <bpmndi:BPMNPlane bpmnElement=\"newmodel_verify_20261006\" id=\"BPMNPlane_newmodel_verify_20261006\"></bpmndi:BPMNPlane>\n  </bpmndi:BPMNDiagram>\n</definitions>',0),('297507',1,'hist.var-wfMiAssignees_UserTask_2',NULL,_binary '�\�\0sr\0java.util.ArrayListx�\��\�a�\0I\0sizexp\0\0\0w\0\0\0sr\0java.lang.Long;�\�̏#\�\0J\0valuexr\0java.lang.Number����\��\0\0xp�\�,\�\��x',NULL),('297527',1,'newmodel_verify_20261006.bpmn20.xml','297526',_binary '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<de