  `imagefilename` varchar(500) DEFAULT NULL COMMENT '原始文件名',
  `imagefiletype` varchar(100) DEFAULT NULL COMMENT '文件类型（MIME类型）',
  `imagefileused` int DEFAULT '1' COMMENT '是否使用（1=使用）',
  `filerealpath` varchar(1000) DEFAULT NULL COMMENT '文件真实存储路径',
  `iszip` int DEFAULT '0' COMMENT '是否压缩（0/1）',
  `isencrypt` int DEFAULT '0' COMMENT '是否加密（0/1）',
  `fileSize` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `isaesencrypt` int DEFAULT '0' COMMENT '是否AES加密（0/1）',
  `aescode` varchar(50) DEFAULT NULL COMMENT 'AES加密密钥',
