--
-- Table structure for table `mall_category`
--

DROP TABLE IF EXISTS `mall_category`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mall_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '分类描述',
  `parent_id` bigint DEFAULT NULL COMMENT '父分类ID',
  `level` tinyint NOT NULL DEFAULT '1' COMMENT '分类级别：1 顶级，2 二级，3 三级',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序权重',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类图标',
  `image` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '分类图片',
  `banner` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '分类 banner',
  `image_id` bigint DEFAULT NULL COMMENT '分类图片ID（关联ImageFile表主键）',
  `banner_id` bigint DEFAULT NULL COMMENT '分类Banner图片ID（关联ImageFile表主键）',
  `icon_id` bigint DEFAULT NULL COMMENT '分类图标ID（关联ImageFile表主键）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1 正常，0 禁用',
  `tenant_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '租户 ID',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否已删除',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_status` (`status`),
  KEY `idx_mall_category_tenant_id` (`tenant_id`),
  KEY `idx_mall_category_is_deleted` (`is_deleted`),
  KEY `idx_mall_category_image_id` (`image_id`),
  KEY `idx_mall_category_banner_id` (`banner_id`),
  KEY `idx_mall_category_icon_id` (`icon_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2054502310731612163 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='分类表';
/*!40101 SET character_set_client = @saved_cs_client */;

