  KEY `idx_product_id` (`product_id`),
  KEY `idx_mall_order_item_tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2052054997056696323 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单项表';
