  PRIMARY KEY (`id`),
  KEY `idx_node_group` (`node_id`,`group_no`),
  KEY `idx_node_type` (`node_id`,`op_type`)
) ENGINE=InnoDB AUTO_INCREMENT=2107765851999526915 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='节点操作者';
