xmlns:di=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:wf=\"http://www.springblade.org/workflow\" id=\"Definitions_flow_muwww30wps1i\" targetNamespace=\"http://bpmn.io/schema/bpmn\">\n  <bpmn:process id=\"flow_muwww30wps1i\" isExecutable=\"true\">\n    <bpmn:startEvent id=\"StartEvent_1\" name=\"开始\" />\n    <bpmn:sequenceFlow id=\"Flow_1\" sourceRef=\"StartEvent_1\" targetRef=\"UserTask_1\" />\n    <bpmn:userTask id=\"UserTask_1\" name=\"创建\">\n      <bpmn:extensionElements>\n        <wf:node xmlns:wf=\"http://www.springblade.org/workflow\" nodeType=\"0\" sortOrder=\"1\">\n          <wf:operator groupNo=\"1\" opType=\"17\" />\n        </wf:node>\n      </bpmn:extensionElements>\n      <bpmn:outgoing>Flow_0riax23</bpmn:outgoing>\n    </bpmn:userTask>\n    <bpmn:endEvent id=\"EndEvent_1\" name=\"结束\">\n      <bpmn:incoming>Flow_1gmsdh5</bpmn:incoming>\n    </bpmn:endEvent>\n    <bpmn:userTask id=\"UserTask_muxanui60\" name=\"审批1\">\n      <bpmn:extensionElements>\n        <wf:node nodeType=\"1\" sortOrder=\"2\">\n          <wf:operator groupNo=\"1\" opType=\"1\" objId=\"1123598813738675203\" bhxj=\"3\" levelMin=\"0\" levelMax=\"100\" signOrder=\"1\" batchNo=\"0\" groupName=\"审批人\" canView=\"1\" conditionJson=\"{&#34;name&#34;:&#34;审批人&#34;,&#34;logic&#34;:&#34;AND&#34;}\" isCoadjutant=\"0\" isPending=\"0\" isModify=\"0\" />\n          <wf:extJson>{\"settings\":{\"operateMenu\":{\"items\":[{\"key\":\"submit\",\"name\":\"提交\",\"enabled\":true},{\"key\":\"save\",\"name\":\"保存\",\"enabled\":true},{\"key\":\"reject\",\"name\":\"退回\",\"enabled\":true},{\"key\":\"forward\",\"name\":\"转发\",\"enabled\":true},{\"key\":\"forwardRetract\",\"name\":\"转发收回\",\"enabled\":false},{\"key\":\"transfer\",\"name\":\"转办\",\"enabled\":false},{\"key\":\"deliver\",\"name\":\"转交\",\"enabled\":false},{\"key\":\"sign\",\"name\":\"加签\",\"enabled\":false},{\"key\":\"circulate\",\"name\":\"传阅\",\"enabled\":false},{\"key\":\"circulateFb\",\"name\":\"传阅（需反馈）\",\"enabled\":false},{\"key\":\"circulateNoFb\",\"name\":\"传阅（不需反馈）\",\"enabled\":false},{\"key\":\"consult\",\"name\":\"意见征询\",\"enabled\":false},{\"key\":\"consultFb\",\"name\":\"意见征询（需反馈）\",\"enabled\":false},{\"key\":\"consultNoFb\",\"name\":\"意见征询（不需反馈）\",\"enabled\":false},{\"key\":\"consultReply\",\"name\":\"征询回复\",\"enabled\":false},{\"key\":\"consultRetract\",\"name\":\"征询收回\",\"enabled\":false},{\"key\":\"consultTransfer\",\"name\":\"征询转办\",\"enabled\":false},{\"key\":\"opinion\",\"name\":\"填写意见\",\"enabled\":false},{\"key\":\"attach\",\"name\":\"附件\",\"enabled\":false},{\"key\":\"print\",\"name\":\"打印\",\"enabled\":false},{\"key\":\"printLog\",\"name\":\"打印日志\",\"enabled\":false},{\"key\":\"urge\",\"name\":\"催办\",\"enabled\":false},{\"key\":\"timeoutSet\",\"name\":\"超时设置\",\"enabled\":false},{\"key\":\"flowSet\",\"name\":\"流转设定\",\"enabled\":false},{\"key\":\"submitToReject\",\"name\":\"提交至退回节点\",\"enabled\":false},{\"key\":\"read\",\"name\":\"查看\",\"enabled\":false},{\"key\":\"withdraw\",\"name\":\"撤回\",\"enabled\":false},{\"key\":\"stop\",\"name\":\"终止\",\"enabled\":false},{\"key\":\"custom\",\"name\":\"自定义操作\",\"enabled\":false}],\"default\":\"submit\",\"menus\":[\"submit\",\"save\",\"reject\",\"forward\"]}}}</wf:extJson>\n        </wf:node>\n      </bpmn:extensionElements>\n      <bpmn:incoming>Flow_0riax23</bpmn:incoming>\n      <bpmn:outgoing>Flow_1gmsdh5</bpmn:outgoing>\n    </bpmn:userTask>\n    <bpmn:sequenceFlow id=\"Flow_0riax23\" sourceRef=\"UserTask_1\" targetRef=\"UserTask_muxanui60\" />\n    <bpmn:sequenceFlow id=\"Flow_1gmsdh5\" sourceRef=\"UserTask_muxanui60\" targetRef=\"EndEvent_1\" />\n  </bpmn:process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_1\">\n    <bpmndi:BPMNPlane id=\"BPMNPlane_1\" bpmnElement=\"flow_muwww30wps1i\">\n      <bpmndi:BPMNShape id=\"StartEvent_1_di\" bpmnElement=\"StartEvent_1\">\n        <dc:Bounds x=\"160\" y=\"100\" width=\"36\" height=\"36\" />\n        <bpmndi:BPMNLabel>\n          <dc:Bounds x=\"160\" y=\"140\" width=\"36\" height=\"14\" />\n        </bpmndi:BPMNLabel>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"UserTask_1_di\" bpmnElement=\"UserTask_1\">\n        <dc:Bounds x=\"270\" y=\"78\" width=\"100\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"UserTask_muxanui60_di\" bpmnElement=\"UserTask_muxanui60\">\n        <dc:Bounds x=\"400\" y=\"220\" width=\"100\" height=\"80\" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id=\"EndEvent_1_di\" bpmnElement=\"EndEvent_1\">\n        <dc:Bounds x=\"732\" y=\"252\" width=\"36\" height=\"36\" />\n        <bpmndi:BPMNLabel>\n          <dc:Bounds x=\"739\" y=\"292\" width=\"23\" height=\"14\" />\n        </bpmndi:BPMNLabel>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNEdge id=\"Flow_1_di\" bpmnElement=\"Flow_1\">\n        <di:waypoint x=\"196\" y=\"118\" />\n        <di:waypoint x=\"270\" y=\"118\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_0riax23_di\" bpmnElement=\"Flow_0riax23\">\n        <di:waypoint x=\"370\" y=\"118\" />\n        <di:waypoint x=\"450\" y=\"118\" />\n        <di:waypoint x=\"450\" y=\"220\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_1gmsdh5_di\" bpmnElement=\"Flow_1gmsdh5\">\n        <di:waypoint x=\"500\" y=\"260\" />\n        <di:waypoint x=\"735\" y=\"260\" />\n      </bpmndi:BPMNEdge>\n    </bpmndi:BPMNPlane>\n  </bpmndi:BPMNDiagram>\n</bpmn:definitions>\n',1,2107513054141906945,'310075',0,NULL,'2',0,NULL,0,'000000',NULL,NULL,'2026-10-07 00:47:22',NULL,'2026-10-07 10:20:28',1,0,'flow_muwww30wps1i:4:310078',9,'flow_muwww30wps1i__test:2:310023'),(2107717660851638273,'travel_reimburse_approval',NULL,'差旅报销审批流','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<!--\r\n  ============================================================================\r\n  差旅报销审批流 (formtable_main_9 / formId=2104243330272460802)\r\n  Generated per .codebuddy/skills/flowable-workflow-builder\r\n\r\n  路径:\r\n    小额 (<=5000)        : 部门上级 -> 财务审核 -> [付款网关] -> 出纳/归档\r\n    中额 (5000<x<=20000) : 部门上级 -> 分管领导 -> 财务审核 -> ...\r\n    大额 (>20000)        : 部门上级 -> 分管领导 -> 总经理 -> 财务经理复核 -> 财务审核 -> ...\r\n\r\n  说明:\r\n    1. 创建节点 = userTask + nodeType=0（非 startEvent）\r\n    2. 两个网关的 default 流均不带条件\r\n    3. 条件只用 &&，不用 ||（保证流程测试走查与运行一致）\r\n    4. 逐级向上 = 串联节点，未使用 bhxj=3\r\n    5. 部门上级 = opType 18（依赖 blade_user.manager_id）\r\n    ============================================================================\r\n-->\r\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\"\r\n             xmlns:flowable=\"http://flowable.org/bpmn\"\r\n             xmlns:wf=\"http://www.springblade.org/workflow\"\r\n             xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\"\r\n             xmlns:omgdc=\"http://www.omg.org/spec/DD/20100524/DC\"\r\n             xmlns:omgdi=\"http://www.omg.org/spec/DD/20100524/DI\"\r\n             xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\r\n             targetNamespace=\"http://www.springblade.org/workflow\"\r\n             xsi:schemaLocation=\"http://www.omg.org/spec/BPMN/20100524/MODEL http://www.omg.org/spec/BPMN/20100524/DI/BPMN20.xsd\">\r\n\r\n  <process id=\"travel_reimburse_approval\" name=\"差旅报销审批流\" isExecutable=\"true\">\r\n\r\n    <startEvent id=\"StartEvent_1\" name=\"开始\" flowable:initiator=\"initiator\"/>\r\n    <sequenceFlow id=\"F_Start\" name=\"发起\" sourceRef=\"StartEvent_1\" targetRef=\"Task_Create\"/>\r\n\r\n    <userTask id=\"Task_Create\" name=\"申请填单\" flowable:assignee=\"${initiator}\" flowable:formKey=\"travelForm\">\r\n      <documentation>申请人填写差旅报销单。创建节点是真实等待任务，可作为退回目标；发起时由程序立即 complete。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"0\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"17\" value=\"\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"flowno\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqdate\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqman\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqdept\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"traveltype\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"payamt\" perm=\"2\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"remark\" perm=\"2\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Create\" name=\"提交\" sourceRef=\"Task_Create\" targetRef=\"Task_Department\"/>\r\n\r\n    <userTask id=\"Task_Department\" name=\"部门上级审批\" flowable:candidateGroups=\"dept_manager\">\r\n      <documentation>opType=18 创建人上级（即部门上级），依赖 blade_user.manager_id；为空会静默降级为无人可审。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"18\" value=\"\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"部门不批 → 退发起人改单\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"remark\" perm=\"1\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Dept\" name=\"部门通过\" sourceRef=\"Task_Department\" targetRef=\"Gateway_Amount\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Amount\" name=\"金额分级\" default=\"F_Climb\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Small\" name=\"小额≤5000\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_FinReview\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &lt;= 5000}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_Climb\" name=\"超过5000 逐级上报(default)\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_Vice\"/>\r\n\r\n    <userTask id=\"Task_Vice\" name=\"分管领导审批\" flowable:candidateGroups=\"vice_leader\">\r\n      <documentation>opType=2 角色（分管领导）。分管领导/总经理无专用 opType，只能用角色或岗位。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"vice_leader_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"逐级回退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"业务不认可 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Vice\" name=\"分管通过\" sourceRef=\"Task_Vice\" targetRef=\"Gateway_Level\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Level\" name=\"是否需总经理\" default=\"F_ViceToFin\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Large\" name=\"大额>20000\" sourceRef=\"Gateway_Level\" targetRef=\"Task_GM\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &gt; 20000}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_ViceToFin\" name=\"中额 直达财务(default)\" sourceRef=\"Gateway_Level\" targetRef=\"Task_FinReview\"/>\r\n\r\n    <userTask id=\"Task_GM\" name=\"总经理审批\" flowable:candidateGroups=\"gm\">\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"gm_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Vice\" label=\"逐级回退分管领导\"/>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"逐级回退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"退回发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_GM\" name=\"总经理通过\" sourceRef=\"Task_GM\" targetRef=\"Task_FinManager\"/>\r\n\r\n    <userTask id=\"Task_FinManager\" name=\"财务经理复核\" flowable:candidateGroups=\"fin_manager\">\r\n      <documentation>大额路径专用复核；同时作为财务审核节点的加签/转办目标与 exceptionHandle 兜底目标。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"fin_manager_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_FinReview\" label=\"退回财务审核\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"特批不通过 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_FinMgr\" name=\"复核通过\" sourceRef=\"Task_FinManager\" targetRef=\"Task_FinReview\"/>\r\n\r\n    <userTask id=\"Task_FinReview\" name=\"财务审核\" flowable:candidateGroups=\"fin_review\">\r\n      <documentation>核心节点：按问题类型退到不同目标 = 按条件回退（引擎 reject 本身无条件）。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"fin_review_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"circulate\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/><wf:menu code=\"urge\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"票据/数据错 → 退发起人\"/>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"业务不符 → 退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Vice\" label=\"金额异常需裁定 → 退分管领导\"/>\r\n          <wf:reject targetNodeKey=\"Task_GM\" label=\"金额异常需裁定 → 退总经理\"/>\r\n          <wf:reject targetNodeKey=\"Task_FinManager\" label=\"超标需特批 → 退财务经理复核\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"2880\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"dt1\" fieldName=\"ablebudgetamt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"dt3\" fieldName=\"hrmbankaccount\" perm=\"1\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Fin\" name=\"财务通过\" sourceRef=\"Task_FinReview\" targetRef=\"Gateway_Pay\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Pay\" name=\"是否需付款\" default=\"F_NoPay\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Pay\" name=\"需付款\" sourceRef=\"Gateway_Pay\" targetRef=\"Task_Cashier\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${payamt &gt; 0}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_NoPay\" name=\"无需付款(default)\" sourceRef=\"Gateway_Pay\" targetRef=\"EndEvent_Archive\"/>\r\n\r\n    <userTask id=\"Task_Cashier\" name=\"出纳付款确认\" flowable:candidateGroups=\"cashier\">\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"cashier_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_FinReview\" label=\"收款信息错 → 退财务审核\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"收款人信息错 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Cash\" name=\"付款完成\" sourceRef=\"Task_Cashier\" targetRef=\"EndEvent_Archive\"/>\r\n\r\n    <endEvent id=\"EndEvent_Archive\" name=\"归档\">\r\n      <extensionElements><wf:node nodeType=\"3\"/></extensionElements>\r\n    </endEvent>\r\n\r\n  </process>\r\n\r\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_1\">\r\n    <bpmndi:BPMNPlane bpmnElement=\"travel_reimburse_approval\" id=\"BPMNPlane_1\">\r\n      <bpmndi:BPMNShape bpmnElement=\"StartEvent_1\" id=\"StartEvent_1_di\">\r\n        <omgdc:Bounds x=\"60\" y=\"245\" width=\"30\" height=\"30\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Create\" id=\"Task_Create_di\">\r\n        <omgdc:Bounds x=\"130\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Department\" id=\"Task_Department_di\">\r\n        <omgdc:Bounds x=\"300\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Amount\" id=\"Gateway_Amount_di\">\r\n        <omgdc:Bounds x=\"470\" y=\"235\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Vice\" id=\"Task_Vice_di\">\r\n        <omgdc:Bounds x=\"560\" y=\"120\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Level\" id=\"Gateway_Level_di\">\r\n        <omgdc:Bounds x=\"730\" y=\"135\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_GM\" id=\"Task_GM_di\">\r\n        <omgdc:Bounds x=\"820\" y=\"40\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_FinManager\" id=\"Task_FinManager_di\">\r\n        <omgdc:Bounds x=\"990\" y=\"40\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_FinReview\" id=\"Task_FinReview_di\">\r\n        <omgdc:Bounds x=\"990\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Pay\" id=\"Gateway_Pay_di\">\r\n        <omgdc:Bounds x=\"1160\" y=\"235\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Cashier\" id=\"Task_Cashier_di\">\r\n        <omgdc:Bounds x=\"1250\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"EndEvent_Archive\" id=\"EndEvent_Archive_di\">\r\n        <omgdc:Bounds x=\"1420\" y=\"245\" width=\"30\" height=\"30\"/>\r\n      </bpmndi:BPMNShape>\r\n\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Start\" id=\"F_Start_di\">\r\n        <omgdi:waypoint x=\"90\" y=\"260\"/><omgdi:waypoint x=\"130\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Create\" id=\"F_Create_di\">\r\n        <omgdi:waypoint x=\"250\" y=\"260\"/><omgdi:waypoint x=\"300\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Dept\" id=\"F_Dept_di\">\r\n        <omgdi:waypoint x=\"420\" y=\"260\"/><omgdi:waypoint x=\"470\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Small\" id=\"F_Small_di\">\r\n        <omgdi:waypoint x=\"490\" y=\"285\"/><omgdi:waypoint x=\"490\" y=\"340\"/>\r\n        <omgdi:waypoint x=\"1050\" y=\"340\"/><omgdi:waypoint x=\"1050\" y=\"300\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Climb\" id=\"F_Climb_di\">\r\n        <omgdi:waypoint x=\"490\" y=\"235\"/><omgdi:waypoint x=\"490\" y=\"160\"/>\r\n        <omgdi:waypoint x=\"560\" y=\"160\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Vice\" id=\"F_Vice_di\">\r\n        <omgdi:waypoint x=\"680\" y=\"160\"/><omgdi:waypoint x=\"730\" y=\"160\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Large\" id=\"F_Large_di\">\r\n        <omgdi:waypoint x=\"750\" y=\"135\"/><omgdi:waypoint x=\"750\" y=\"80\"/>\r\n        <omgdi:waypoint x=\"820\" y=\"80\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_ViceToFin\" id=\"F_ViceToFin_di\">\r\n        <omgdi:waypoint x=\"770\" y=\"160\"/><omgdi:waypoint x=\"900\" y=\"160\"/>\r\n        <omgdi:waypoint x=\"900\" y=\"260\"/><omgdi:waypoint x=\"990\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_GM\" id=\"F_GM_di\">\r\n        <omgdi:waypoint x=\"940\" y=\"80\"/><omgdi:waypoint x=\"990\" y=\"80\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_FinMgr\" id=\"F_FinMgr_di\">\r\n        <omgdi:waypoint x=\"1050\" y=\"120\"/><omgdi:waypoint x=\"1050\" y=\"220\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Fin\" id=\"F_Fin_di\">\r\n        <omgdi:waypoint x=\"1110\" y=\"260\"/><omgdi:waypoint x=\"1160\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Pay\" id=\"F_Pay_di\">\r\n        <omgdi:waypoint x=\"1180\" y=\"285\"/><omgdi:waypoint x=\"1180\" y=\"320\"/>\r\n        <omgdi:waypoint x=\"1310\" y=\"320\"/><omgdi:waypoint x=\"1310\" y=\"300\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_NoPay\" id=\"F_NoPay_di\">\r\n        <omgdi:waypoint x=\"1180\" y=\"235\"/><omgdi:waypoint x=\"1180\" y=\"190\"/>\r\n        <omgdi:waypoint x=\"1435\" y=\"190\"/><omgdi:waypoint x=\"1435\" y=\"245\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Cash\" id=\"F_Cash_di\">\r\n        <omgdi:waypoint x=\"1370\" y=\"260\"/><omgdi:waypoint x=\"1420\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n    </bpmndi:BPMNPlane>\r\n  </bpmndi:BPMNDiagram>\r\n\r\n</definitions>',1,2107717660851638273,NULL,0,NULL,NULL,NULL,NULL,0,'000000',NULL,NULL,'2026-10-07 14:20:24',NULL,'2026-10-07 14:22:01',0,1,NULL,1,NULL),(2107717661241708545,'travel_reimburse_approval_2',NULL,'差旅报销审批流','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<!--\r\n  ============================================================================\r\n  差旅报销审批流 (formtable_main_9 / formId=2104243330272460802)\r\n  Generated per .codebuddy/skills/flowable-workflow-builder\r\n\r\n  路径:\r\n    小额 (<=5000)        : 部门上级 -> 财务审核 -> [付款网关] -> 出纳/归档\r\n    中额 (5000<x<=20000) : 部门上级 -> 分管领导 -> 财务审核 -> ...\r\n    大额 (>20000)        : 部门上级 -> 分管领导 -> 总经理 -> 财务经理复核 -> 财务审核 -> ...\r\n\r\n  说明:\r\n    1. 创建节点 = userTask + nodeType=0（非 startEvent）\r\n    2. 两个网关的 default 流均不带条件\r\n    3. 条件只用 &&，不用 ||（保证流程测试走查与运行一致）\r\n    4. 逐级向上 = 串联节点，未使用 bhxj=3\r\n    5. 部门上级 = opType 18（依赖 blade_user.manager_id）\r\n    ============================================================================\r\n-->\r\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\"\r\n             xmlns:flowable=\"http://flowable.org/bpmn\"\r\n             xmlns:wf=\"http://www.springblade.org/workflow\"\r\n             xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\"\r\n             xmlns:omgdc=\"http://www.omg.org/spec/DD/20100524/DC\"\r\n             xmlns:omgdi=\"http://www.omg.org/spec/DD/20100524/DI\"\r\n             xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\r\n             targetNamespace=\"http://www.springblade.org/workflow\"\r\n             xsi:schemaLocation=\"http://www.omg.org/spec/BPMN/20100524/MODEL http://www.omg.org/spec/BPMN/20100524/DI/BPMN20.xsd\">\r\n\r\n  <process id=\"travel_reimburse_approval\" name=\"差旅报销审批流\" isExecutable=\"true\">\r\n\r\n    <startEvent id=\"StartEvent_1\" name=\"开始\" flowable:initiator=\"initiator\"/>\r\n    <sequenceFlow id=\"F_Start\" name=\"发起\" sourceRef=\"StartEvent_1\" targetRef=\"Task_Create\"/>\r\n\r\n    <userTask id=\"Task_Create\" name=\"申请填单\" flowable:assignee=\"${initiator}\" flowable:formKey=\"travelForm\">\r\n      <documentation>申请人填写差旅报销单。创建节点是真实等待任务，可作为退回目标；发起时由程序立即 complete。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"0\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"17\" value=\"\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"flowno\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqdate\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqman\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqdept\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"traveltype\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"payamt\" perm=\"2\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"remark\" perm=\"2\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Create\" name=\"提交\" sourceRef=\"Task_Create\" targetRef=\"Task_Department\"/>\r\n\r\n    <userTask id=\"Task_Department\" name=\"部门上级审批\" flowable:candidateGroups=\"dept_manager\">\r\n      <documentation>opType=18 创建人上级（即部门上级），依赖 blade_user.manager_id；为空会静默降级为无人可审。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"18\" value=\"\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"部门不批 → 退发起人改单\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"remark\" perm=\"1\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Dept\" name=\"部门通过\" sourceRef=\"Task_Department\" targetRef=\"Gateway_Amount\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Amount\" name=\"金额分级\" default=\"F_Climb\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Small\" name=\"小额≤5000\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_FinReview\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &lt;= 5000}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_Climb\" name=\"超过5000 逐级上报(default)\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_Vice\"/>\r\n\r\n    <userTask id=\"Task_Vice\" name=\"分管领导审批\" flowable:candidateGroups=\"vice_leader\">\r\n      <documentation>opType=2 角色（分管领导）。分管领导/总经理无专用 opType，只能用角色或岗位。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"vice_leader_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"逐级回退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"业务不认可 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Vice\" name=\"分管通过\" sourceRef=\"Task_Vice\" targetRef=\"Gateway_Level\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Level\" name=\"是否需总经理\" default=\"F_ViceToFin\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Large\" name=\"大额>20000\" sourceRef=\"Gateway_Level\" targetRef=\"Task_GM\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &gt; 20000}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_ViceToFin\" name=\"中额 直达财务(default)\" sourceRef=\"Gateway_Level\" targetRef=\"Task_FinReview\"/>\r\n\r\n    <userTask id=\"Task_GM\" name=\"总经理审批\" flowable:candidateGroups=\"gm\">\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"gm_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Vice\" label=\"逐级回退分管领导\"/>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"逐级回退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"退回发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_GM\" name=\"总经理通过\" sourceRef=\"Task_GM\" targetRef=\"Task_FinManager\"/>\r\n\r\n    <userTask id=\"Task_FinManager\" name=\"财务经理复核\" flowable:candidateGroups=\"fin_manager\">\r\n      <documentation>大额路径专用复核；同时作为财务审核节点的加签/转办目标与 exceptionHandle 兜底目标。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"fin_manager_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_FinReview\" label=\"退回财务审核\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"特批不通过 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_FinMgr\" name=\"复核通过\" sourceRef=\"Task_FinManager\" targetRef=\"Task_FinReview\"/>\r\n\r\n    <userTask id=\"Task_FinReview\" name=\"财务审核\" flowable:candidateGroups=\"fin_review\">\r\n      <documentation>核心节点：按问题类型退到不同目标 = 按条件回退（引擎 reject 本身无条件）。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"fin_review_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"circulate\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/><wf:menu code=\"urge\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"票据/数据错 → 退发起人\"/>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"业务不符 → 退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Vice\" label=\"金额异常需裁定 → 退分管领导\"/>\r\n          <wf:reject targetNodeKey=\"Task_GM\" label=\"金额异常需裁定 → 退总经理\"/>\r\n          <wf:reject targetNodeKey=\"Task_FinManager\" label=\"超标需特批 → 退财务经理复核\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"2880\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"dt1\" fieldName=\"ablebudgetamt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"dt3\" fieldName=\"hrmbankaccount\" perm=\"1\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Fin\" name=\"财务通过\" sourceRef=\"Task_FinReview\" targetRef=\"Gateway_Pay\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Pay\" name=\"是否需付款\" default=\"F_NoPay\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Pay\" name=\"需付款\" sourceRef=\"Gateway_Pay\" targetRef=\"Task_Cashier\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${payamt &gt; 0}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_NoPay\" name=\"无需付款(default)\" sourceRef=\"Gateway_Pay\" targetRef=\"EndEvent_Archive\"/>\r\n\r\n    <userTask id=\"Task_Cashier\" name=\"出纳付款确认\" flowable:candidateGroups=\"cashier\">\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"cashier_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_FinReview\" label=\"收款信息错 → 退财务审核\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"收款人信息错 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Cash\" name=\"付款完成\" sourceRef=\"Task_Cashier\" targetRef=\"EndEvent_Archive\"/>\r\n\r\n    <endEvent id=\"EndEvent_Archive\" name=\"归档\">\r\n      <extensionElements><wf:node nodeType=\"3\"/></extensionElements>\r\n    </endEvent>\r\n\r\n  </process>\r\n\r\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_1\">\r\n    <bpmndi:BPMNPlane bpmnElement=\"travel_reimburse_approval\" id=\"BPMNPlane_1\">\r\n      <bpmndi:BPMNShape bpmnElement=\"StartEvent_1\" id=\"StartEvent_1_di\">\r\n        <omgdc:Bounds x=\"60\" y=\"245\" width=\"30\" height=\"30\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Create\" id=\"Task_Create_di\">\r\n        <omgdc:Bounds x=\"130\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Department\" id=\"Task_Department_di\">\r\n        <omgdc:Bounds x=\"300\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Amount\" id=\"Gateway_Amount_di\">\r\n        <omgdc:Bounds x=\"470\" y=\"235\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Vice\" id=\"Task_Vice_di\">\r\n        <omgdc:Bounds x=\"560\" y=\"120\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Level\" id=\"Gateway_Level_di\">\r\n        <omgdc:Bounds x=\"730\" y=\"135\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_GM\" id=\"Task_GM_di\">\r\n        <omgdc:Bounds x=\"820\" y=\"40\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_FinManager\" id=\"Task_FinManager_di\">\r\n        <omgdc:Bounds x=\"990\" y=\"40\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_FinReview\" id=\"Task_FinReview_di\">\r\n        <omgdc:Bounds x=\"990\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Pay\" id=\"Gateway_Pay_di\">\r\n        <omgdc:Bounds x=\"1160\" y=\"235\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Cashier\" id=\"Task_Cashier_di\">\r\n        <omgdc:Bounds x=\"1250\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"EndEvent_Archive\" id=\"EndEvent_Archive_di\">\r\n        <omgdc:Bounds x=\"1420\" y=\"245\" width=\"30\" height=\"30\"/>\r\n      </bpmndi:BPMNShape>\r\n\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Start\" id=\"F_Start_di\">\r\n        <omgdi:waypoint x=\"90\" y=\"260\"/><omgdi:waypoint x=\"130\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Create\" id=\"F_Create_di\">\r\n        <omgdi:waypoint x=\"250\" y=\"260\"/><omgdi:waypoint x=\"300\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Dept\" id=\"F_Dept_di\">\r\n        <omgdi:waypoint x=\"420\" y=\"260\"/><omgdi:waypoint x=\"470\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Small\" id=\"F_Small_di\">\r\n        <omgdi:waypoint x=\"490\" y=\"285\"/><omgdi:waypoint x=\"490\" y=\"340\"/>\r\n        <omgdi:waypoint x=\"1050\" y=\"340\"/><omgdi:waypoint x=\"1050\" y=\"300\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Climb\" id=\"F_Climb_di\">\r\n        <omgdi:waypoint x=\"490\" y=\"235\"/><omgdi:waypoint x=\"490\" y=\"160\"/>\r\n        <omgdi:waypoint x=\"560\" y=\"160\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Vice\" id=\"F_Vice_di\">\r\n        <omgdi:waypoint x=\"680\" y=\"160\"/><omgdi:waypoint x=\"730\" y=\"160\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Large\" id=\"F_Large_di\">\r\n        <omgdi:waypoint x=\"750\" y=\"135\"/><omgdi:waypoint x=\"750\" y=\"80\"/>\r\n        <omgdi:waypoint x=\"820\" y=\"80\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_ViceToFin\" id=\"F_ViceToFin_di\">\r\n        <omgdi:waypoint x=\"770\" y=\"160\"/><omgdi:waypoint x=\"900\" y=\"160\"/>\r\n        <omgdi:waypoint x=\"900\" y=\"260\"/><omgdi:waypoint x=\"990\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_GM\" id=\"F_GM_di\">\r\n        <omgdi:waypoint x=\"940\" y=\"80\"/><omgdi:waypoint x=\"990\" y=\"80\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_FinMgr\" id=\"F_FinMgr_di\">\r\n        <omgdi:waypoint x=\"1050\" y=\"120\"/><omgdi:waypoint x=\"1050\" y=\"220\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Fin\" id=\"F_Fin_di\">\r\n        <omgdi:waypoint x=\"1110\" y=\"260\"/><omgdi:waypoint x=\"1160\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Pay\" id=\"F_Pay_di\">\r\n        <omgdi:waypoint x=\"1180\" y=\"285\"/><omgdi:waypoint x=\"1180\" y=\"320\"/>\r\n        <omgdi:waypoint x=\"1310\" y=\"320\"/><omgdi:waypoint x=\"1310\" y=\"300\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_NoPay\" id=\"F_NoPay_di\">\r\n        <omgdi:waypoint x=\"1180\" y=\"235\"/><omgdi:waypoint x=\"1180\" y=\"190\"/>\r\n        <omgdi:waypoint x=\"1435\" y=\"190\"/><omgdi:waypoint x=\"1435\" y=\"245\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Cash\" id=\"F_Cash_di\">\r\n        <omgdi:waypoint x=\"1370\" y=\"260\"/><omgdi:waypoint x=\"1420\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n    </bpmndi:BPMNPlane>\r\n  </bpmndi:BPMNDiagram>\r\n\r\n</definitions>',1,2107717661241708545,NULL,0,NULL,NULL,NULL,NULL,0,'000000',NULL,NULL,'2026-10-07 14:20:24',NULL,'2026-10-07 14:22:01',0,1,NULL,1,NULL),(2107717661501755394,'travel_reimburse_approval_3',NULL,'差旅报销审批流','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<!--\r\n  ============================================================================\r\n  差旅报销审批流 (formtable_main_9 / formId=2104243330272460802)\r\n  Generated per .codebuddy/skills/flowable-workflow-builder\r\n\r\n  路径:\r\n    小额 (<=5000)        : 部门上级 -> 财务审核 -> [付款网关] -> 出纳/归档\r\n    中额 (5000<x<=20000) : 部门上级 -> 分管领导 -> 财务审核 -> ...\r\n    大额 (>20000)        : 部门上级 -> 分管领导 -> 总经理 -> 财务经理复核 -> 财务审核 -> ...\r\n\r\n  说明:\r\n    1. 创建节点 = userTask + nodeType=0（非 startEvent）\r\n    2. 两个网关的 default 流均不带条件\r\n    3. 条件只用 &&，不用 ||（保证流程测试走查与运行一致）\r\n    4. 逐级向上 = 串联节点，未使用 bhxj=3\r\n    5. 部门上级 = opType 18（依赖 blade_user.manager_id）\r\n    ============================================================================\r\n-->\r\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\"\r\n             xmlns:flowable=\"http://flowable.org/bpmn\"\r\n             xmlns:wf=\"http://www.springblade.org/workflow\"\r\n             xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\"\r\n             xmlns:omgdc=\"http://www.omg.org/spec/DD/20100524/DC\"\r\n             xmlns:omgdi=\"http://www.omg.org/spec/DD/20100524/DI\"\r\n             xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\r\n             targetNamespace=\"http://www.springblade.org/workflow\"\r\n             xsi:schemaLocation=\"http://www.omg.org/spec/BPMN/20100524/MODEL http://www.omg.org/spec/BPMN/20100524/DI/BPMN20.xsd\">\r\n\r\n  <process id=\"travel_reimburse_approval\" name=\"差旅报销审批流\" isExecutable=\"true\">\r\n\r\n    <startEvent id=\"StartEvent_1\" name=\"开始\" flowable:initiator=\"initiator\"/>\r\n    <sequenceFlow id=\"F_Start\" name=\"发起\" sourceRef=\"StartEvent_1\" targetRef=\"Task_Create\"/>\r\n\r\n    <userTask id=\"Task_Create\" name=\"申请填单\" flowable:assignee=\"${initiator}\" flowable:formKey=\"travelForm\">\r\n      <documentation>申请人填写差旅报销单。创建节点是真实等待任务，可作为退回目标；发起时由程序立即 complete。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"0\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"17\" value=\"\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"flowno\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqdate\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqman\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"reqdept\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"traveltype\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"payamt\" perm=\"2\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"remark\" perm=\"2\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Create\" name=\"提交\" sourceRef=\"Task_Create\" targetRef=\"Task_Department\"/>\r\n\r\n    <userTask id=\"Task_Department\" name=\"部门上级审批\" flowable:candidateGroups=\"dept_manager\">\r\n      <documentation>opType=18 创建人上级（即部门上级），依赖 blade_user.manager_id；为空会静默降级为无人可审。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"18\" value=\"\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"部门不批 → 退发起人改单\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"remark\" perm=\"1\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Dept\" name=\"部门通过\" sourceRef=\"Task_Department\" targetRef=\"Gateway_Amount\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Amount\" name=\"金额分级\" default=\"F_Climb\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Small\" name=\"小额≤5000\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_FinReview\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &lt;= 5000}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_Climb\" name=\"超过5000 逐级上报(default)\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_Vice\"/>\r\n\r\n    <userTask id=\"Task_Vice\" name=\"分管领导审批\" flowable:candidateGroups=\"vice_leader\">\r\n      <documentation>opType=2 角色（分管领导）。分管领导/总经理无专用 opType，只能用角色或岗位。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"vice_leader_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"逐级回退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"业务不认可 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Vice\" name=\"分管通过\" sourceRef=\"Task_Vice\" targetRef=\"Gateway_Level\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Level\" name=\"是否需总经理\" default=\"F_ViceToFin\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Large\" name=\"大额>20000\" sourceRef=\"Gateway_Level\" targetRef=\"Task_GM\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &gt; 20000}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_ViceToFin\" name=\"中额 直达财务(default)\" sourceRef=\"Gateway_Level\" targetRef=\"Task_FinReview\"/>\r\n\r\n    <userTask id=\"Task_GM\" name=\"总经理审批\" flowable:candidateGroups=\"gm\">\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"gm_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Vice\" label=\"逐级回退分管领导\"/>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"逐级回退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"退回发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_GM\" name=\"总经理通过\" sourceRef=\"Task_GM\" targetRef=\"Task_FinManager\"/>\r\n\r\n    <userTask id=\"Task_FinManager\" name=\"财务经理复核\" flowable:candidateGroups=\"fin_manager\">\r\n      <documentation>大额路径专用复核；同时作为财务审核节点的加签/转办目标与 exceptionHandle 兜底目标。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"fin_manager_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_FinReview\" label=\"退回财务审核\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"特批不通过 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_FinMgr\" name=\"复核通过\" sourceRef=\"Task_FinManager\" targetRef=\"Task_FinReview\"/>\r\n\r\n    <userTask id=\"Task_FinReview\" name=\"财务审核\" flowable:candidateGroups=\"fin_review\">\r\n      <documentation>核心节点：按问题类型退到不同目标 = 按条件回退（引擎 reject 本身无条件）。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"fin_review_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"save\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"forward\"/><wf:menu code=\"transfer\"/><wf:menu code=\"sign\"/>\r\n          <wf:menu code=\"circulate\"/><wf:menu code=\"attach\"/>\r\n          <wf:menu code=\"opinion\"/><wf:menu code=\"print\"/><wf:menu code=\"urge\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"票据/数据错 → 退发起人\"/>\r\n          <wf:reject targetNodeKey=\"Task_Department\" label=\"业务不符 → 退部门上级\"/>\r\n          <wf:reject targetNodeKey=\"Task_Vice\" label=\"金额异常需裁定 → 退分管领导\"/>\r\n          <wf:reject targetNodeKey=\"Task_GM\" label=\"金额异常需裁定 → 退总经理\"/>\r\n          <wf:reject targetNodeKey=\"Task_FinManager\" label=\"超标需特批 → 退财务经理复核\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"2880\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:timeouts>\r\n        <wf:fieldPerms>\r\n          <wf:fieldPerm scope=\"main\" fieldName=\"eeramt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"dt1\" fieldName=\"ablebudgetamt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"dt3\" fieldName=\"hrmbankaccount\" perm=\"1\"/>\r\n        </wf:fieldPerms>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Fin\" name=\"财务通过\" sourceRef=\"Task_FinReview\" targetRef=\"Gateway_Pay\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Pay\" name=\"是否需付款\" default=\"F_NoPay\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Pay\" name=\"需付款\" sourceRef=\"Gateway_Pay\" targetRef=\"Task_Cashier\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${payamt &gt; 0}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_NoPay\" name=\"无需付款(default)\" sourceRef=\"Gateway_Pay\" targetRef=\"EndEvent_Archive\"/>\r\n\r\n    <userTask id=\"Task_Cashier\" name=\"出纳付款确认\" flowable:candidateGroups=\"cashier\">\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\"/>\r\n        <wf:operators>\r\n          <wf:operator type=\"2\" value=\"cashier_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n        </wf:operators>\r\n        <wf:operateMenus>\r\n          <wf:menu code=\"submit\"/><wf:menu code=\"reject\"/>\r\n          <wf:menu code=\"attach\"/><wf:menu code=\"opinion\"/><wf:menu code=\"print\"/>\r\n        </wf:operateMenus>\r\n        <wf:rejects>\r\n          <wf:reject targetNodeKey=\"Task_FinReview\" label=\"收款信息错 → 退财务审核\"/>\r\n          <wf:reject targetNodeKey=\"Task_Create\" label=\"收款人信息错 → 退发起人\"/>\r\n        </wf:rejects>\r\n        <wf:timeouts>\r\n          <wf:timeout startType=\"1\" endType=\"1\" minutes=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:timeouts>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Cash\" name=\"付款完成\" sourceRef=\"Task_Cashier\" targetRef=\"EndEvent_Archive\"/>\r\n\r\n    <endEvent id=\"EndEvent_Archive\" name=\"归档\">\r\n      <extensionElements><wf:node nodeType=\"3\"/></extensionElements>\r\n    </endEvent>\r\n\r\n  </process>\r\n\r\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_1\">\r\n    <bpmndi:BPMNPlane bpmnElement=\"travel_reimburse_approval\" id=\"BPMNPlane_1\">\r\n      <bpmndi:BPMNShape bpmnElement=\"StartEvent_1\" id=\"StartEvent_1_di\">\r\n        <omgdc:Bounds x=\"60\" y=\"245\" width=\"30\" height=\"30\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Create\" id=\"Task_Create_di\">\r\n        <omgdc:Bounds x=\"130\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Department\" id=\"Task_Department_di\">\r\n        <omgdc:Bounds x=\"300\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Amount\" id=\"Gateway_Amount_di\">\r\n        <omgdc:Bounds x=\"470\" y=\"235\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Vice\" id=\"Task_Vice_di\">\r\n        <omgdc:Bounds x=\"560\" y=\"120\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Level\" id=\"Gateway_Level_di\">\r\n        <omgdc:Bounds x=\"730\" y=\"135\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_GM\" id=\"Task_GM_di\">\r\n        <omgdc:Bounds x=\"820\" y=\"40\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_FinManager\" id=\"Task_FinManager_di\">\r\n        <omgdc:Bounds x=\"990\" y=\"40\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_FinReview\" id=\"Task_FinReview_di\">\r\n        <omgdc:Bounds x=\"990\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Pay\" id=\"Gateway_Pay_di\">\r\n        <omgdc:Bounds x=\"1160\" y=\"235\" width=\"40\" height=\"50\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"Task_Cashier\" id=\"Task_Cashier_di\">\r\n        <omgdc:Bounds x=\"1250\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"EndEvent_Archive\" id=\"EndEvent_Archive_di\">\r\n        <omgdc:Bounds x=\"1420\" y=\"245\" width=\"30\" height=\"30\"/>\r\n      </bpmndi:BPMNShape>\r\n\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Start\" id=\"F_Start_di\">\r\n        <omgdi:waypoint x=\"90\" y=\"260\"/><omgdi:waypoint x=\"130\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Create\" id=\"F_Create_di\">\r\n        <omgdi:waypoint x=\"250\" y=\"260\"/><omgdi:waypoint x=\"300\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Dept\" id=\"F_Dept_di\">\r\n        <omgdi:waypoint x=\"420\" y=\"260\"/><omgdi:waypoint x=\"470\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Small\" id=\"F_Small_di\">\r\n        <omgdi:waypoint x=\"490\" y=\"285\"/><omgdi:waypoint x=\"490\" y=\"340\"/>\r\n        <omgdi:waypoint x=\"1050\" y=\"340\"/><omgdi:waypoint x=\"1050\" y=\"300\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Climb\" id=\"F_Climb_di\">\r\n        <omgdi:waypoint x=\"490\" y=\"235\"/><omgdi:waypoint x=\"490\" y=\"160\"/>\r\n        <omgdi:waypoint x=\"560\" y=\"160\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Vice\" id=\"F_Vice_di\">\r\n        <omgdi:waypoint x=\"680\" y=\"160\"/><omgdi:waypoint x=\"730\" y=\"160\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Large\" id=\"F_Large_di\">\r\n        <omgdi:waypoint x=\"750\" y=\"135\"/><omgdi:waypoint x=\"750\" y=\"80\"/>\r\n        <omgdi:waypoint x=\"820\" y=\"80\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_ViceToFin\" id=\"F_ViceToFin_di\">\r\n        <omgdi:waypoint x=\"770\" y=\"160\"/><omgdi:waypoint x=\"900\" y=\"160\"/>\r\n        <omgdi:waypoint x=\"900\" y=\"260\"/><omgdi:waypoint x=\"990\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_GM\" id=\"F_GM_di\">\r\n        <omgdi:waypoint x=\"940\" y=\"80\"/><omgdi:waypoint x=\"990\" y=\"80\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_FinMgr\" id=\"F_FinMgr_di\">\r\n        <omgdi:waypoint x=\"1050\" y=\"120\"/><omgdi:waypoint x=\"1050\" y=\"220\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Fin\" id=\"F_Fin_di\">\r\n        <omgdi:waypoint x=\"1110\" y=\"260\"/><omgdi:waypoint x=\"1160\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Pay\" id=\"F_Pay_di\">\r\n        <omgdi:waypoint x=\"1180\" y=\"285\"/><omgdi:waypoint x=\"1180\" y=\"320\"/>\r\n        <omgdi:waypoint x=\"1310\" y=\"320\"/><omgdi:waypoint x=\"1310\" y=\"300\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_NoPay\" id=\"F_NoPay_di\">\r\n        <omgdi:waypoint x=\"1180\" y=\"235\"/><omgdi:waypoint x=\"1180\" y=\"190\"/>\r\n        <omgdi:waypoint x=\"1435\" y=\"190\"/><omgdi:waypoint x=\"1435\" y=\"245\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Cash\" id=\"F_Cash_di\">\r\n        <omgdi:waypoint x=\"1370\" y=\"260\"/><omgdi:waypoint x=\"1420\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n    </bpmndi:BPMNPlane>\r\n  </bpmndi:BPMNDiagram>\r\n\r\n</definitions>',1,2107717661501755394,NULL,0,NULL,NULL,NULL,NULL,0,'000000',NULL,NULL,'2026-10-07 14:20:24',NULL,'2026-10-07 14:33:29',0,1,NULL,1,NULL),(2107719529330184193,'travel_reimburse_approval_v2',NULL,'差旅报销审批流v2','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<!--\r\n  ============================================================================\r\n  差旅报销审批流 (formtable_main_9 / formId=2104243330272460802)\r\n\r\n  路径:\r\n    小额 (<=5000)        : 部门上级 -> 财务审核 -> [付款网关] -> 出纳/归档\r\n    中额 (5000<x<=20000) : 部门上级 -> 分管领导 -> 财务审核 -> ...\r\n    大额 (>20000)        : 部门上级 -> 分管领导 -> 总经理 -> 财务经理复核 -> 财务审核 -> ...\r\n\r\n  ⚠️ wf: 扩展必须遵循导入器真实契约 (WfDefinitionServiceImpl:1090-1201):\r\n    1. 操作者/字段权限/超时 全部必须【嵌在 wf:node 内部】(平行容器 wf:operators 等会被跳过)\r\n    2. operator 属性是 opType / objId  (不是 type / value)\r\n    3. fieldPerm 是【单数】, 属性是 field (不是 fieldName)\r\n    4. timeout 属性是 durationMin     (不是 minutes)\r\n    5. signOrder 不写时默认 1=会签, 想要或签必须显式写 signOrder=\"0\"\r\n    6. 节点操作菜单(提交/退回/...)不在 wf: 里, 走 ext_json.settings.operateMenu.menus (REST 配置)\r\n  ============================================================================\r\n-->\r\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\"\r\n             xmlns:flowable=\"http://flowable.org/bpmn\"\r\n             xmlns:wf=\"http://www.springblade.org/workflow\"\r\n             xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\"\r\n             xmlns:omgdc=\"http://www.omg.org/spec/DD/20100524/DC\"\r\n             xmlns:omgdi=\"http://www.omg.org/spec/DD/20100524/DI\"\r\n             xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\r\n             targetNamespace=\"http://www.springblade.org/workflow\"\r\n             xsi:schemaLocation=\"http://www.omg.org/spec/BPMN/20100524/MODEL http://www.omg.org/spec/BPMN/20100524/DI/BPMN20.xsd\">\r\n\r\n  <process id=\"travel_reimburse_approval_v2\" name=\"差旅报销审批流\" isExecutable=\"true\">\r\n\r\n    <startEvent id=\"StartEvent_1\" name=\"开始\" flowable:initiator=\"initiator\"/>\r\n    <sequenceFlow id=\"F_Start\" name=\"发起\" sourceRef=\"StartEvent_1\" targetRef=\"Task_Create\"/>\r\n\r\n    <userTask id=\"Task_Create\" name=\"申请填单\" flowable:assignee=\"${initiator}\" flowable:formKey=\"travelForm\">\r\n      <documentation>创建节点 = userTask + wf:node nodeType=0。发起时由程序立即 complete，可作为退回目标。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"0\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\r\n          <wf:operator opType=\"17\" objId=\"\" signOrder=\"0\" bhxj=\"0\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"flowno\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"reqdate\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"reqman\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"reqdept\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"traveltype\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"eeramt\" perm=\"3\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"payamt\" perm=\"2\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"remark\" perm=\"2\"/>\r\n        </wf:node>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Create\" name=\"提交\" sourceRef=\"Task_Create\" targetRef=\"Task_Department\"/>\r\n\r\n    <userTask id=\"Task_Department\" name=\"部门上级审批\" flowable:candidateGroups=\"dept_manager\">\r\n      <documentation>opType=18 创建人上级（即部门上级），依赖 blade_user.manager_id；为空会静默降级为无人可审。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\r\n          <wf:operator opType=\"18\" objId=\"\" signOrder=\"0\" bhxj=\"0\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"eeramt\" perm=\"1\"/>\r\n          <wf:fieldPerm scope=\"main\" field=\"remark\" perm=\"1\"/>\r\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:node>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Dept\" name=\"部门通过\" sourceRef=\"Task_Department\" targetRef=\"Gateway_Amount\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Amount\" name=\"金额分级\" default=\"F_Climb\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Small\" name=\"小额≤5000\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_FinReview\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &lt;= 5000}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_Climb\" name=\"超过5000 逐级上报(default)\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_Vice\"/>\r\n\r\n    <userTask id=\"Task_Vice\" name=\"分管领导审批\" flowable:candidateGroups=\"vice_leader\">\r\n      <documentation>opType=2 角色（分管领导）。分管领导/总经理无专用 opType，只能用角色或岗位。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\r\n          <wf:operator opType=\"2\" objId=\"vice_leader_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:node>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_Vice\" name=\"分管通过\" sourceRef=\"Task_Vice\" targetRef=\"Gateway_Level\"/>\r\n\r\n    <exclusiveGateway id=\"Gateway_Level\" name=\"是否需总经理\" default=\"F_ViceToFin\">\r\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\r\n    </exclusiveGateway>\r\n    <sequenceFlow id=\"F_Large\" name=\"大额>20000\" sourceRef=\"Gateway_Level\" targetRef=\"Task_GM\">\r\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &gt; 20000}</conditionExpression>\r\n    </sequenceFlow>\r\n    <sequenceFlow id=\"F_ViceToFin\" name=\"中额 直达财务(default)\" sourceRef=\"Gateway_Level\" targetRef=\"Task_FinReview\"/>\r\n\r\n    <userTask id=\"Task_GM\" name=\"总经理审批\" flowable:candidateGroups=\"gm\">\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\r\n          <wf:operator opType=\"2\" objId=\"gm_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\r\n        </wf:node>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_GM\" name=\"总经理通过\" sourceRef=\"Task_GM\" targetRef=\"Task_FinManager\"/>\r\n\r\n    <userTask id=\"Task_FinManager\" name=\"财务经理复核\" flowable:candidateGroups=\"fin_manager\">\r\n      <documentation>大额路径专用复核；同时作为财务审核节点的加签/转办目标与 exceptionHandle 兜底目标。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\r\n          <wf:operator opType=\"2\" objId=\"fin_manager_role_id\" signOrder=\"0\" bhxj=\"0\"/>\r\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\r\n        </wf:node>\r\n      </extensionElements>\r\n    </userTask>\r\n    <sequenceFlow id=\"F_FinMgr\" name=\"复核通过\" sourceRef=\"Task_FinManager\" targetRef=\"Task_FinReview\"/>\r\n\r\n    <userTask id=\"Task_FinReview\" name=\"财务审核\" flowable:candidateGroups=\"fin_review\">\r\n      <documentation>核心节点：按问题类型退到不同目标 = 按条件回退（引擎 reject 本身无条件）。</documentation>\r\n      <extensionElements>\r\n        <wf:node nodeType=\"1\" s