Element=\"Task_Cashier\" id=\"Task_Cashier_di\">\r\n        <omgdc:Bounds x=\"1250\" y=\"220\" width=\"120\" height=\"80\"/>\r\n      </bpmndi:BPMNShape>\r\n      <bpmndi:BPMNShape bpmnElement=\"EndEvent_Archive\" id=\"EndEvent_Archive_di\">\r\n        <omgdc:Bounds x=\"1420\" y=\"245\" width=\"30\" height=\"30\"/>\r\n      </bpmndi:BPMNShape>\r\n\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Start\" id=\"F_Start_di\">\r\n        <omgdi:waypoint x=\"90\" y=\"260\"/><omgdi:waypoint x=\"130\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Create\" id=\"F_Create_di\">\r\n        <omgdi:waypoint x=\"250\" y=\"260\"/><omgdi:waypoint x=\"300\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Dept\" id=\"F_Dept_di\">\r\n        <omgdi:waypoint x=\"420\" y=\"260\"/><omgdi:waypoint x=\"470\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Small\" id=\"F_Small_di\">\r\n        <omgdi:waypoint x=\"490\" y=\"285\"/><omgdi:waypoint x=\"490\" y=\"340\"/>\r\n        <omgdi:waypoint x=\"1050\" y=\"340\"/><omgdi:waypoint x=\"1050\" y=\"300\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Climb\" id=\"F_Climb_di\">\r\n        <omgdi:waypoint x=\"490\" y=\"235\"/><omgdi:waypoint x=\"490\" y=\"160\"/>\r\n        <omgdi:waypoint x=\"560\" y=\"160\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Vice\" id=\"F_Vice_di\">\r\n        <omgdi:waypoint x=\"680\" y=\"160\"/><omgdi:waypoint x=\"730\" y=\"160\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Large\" id=\"F_Large_di\">\r\n        <omgdi:waypoint x=\"750\" y=\"135\"/><omgdi:waypoint x=\"750\" y=\"80\"/>\r\n        <omgdi:waypoint x=\"820\" y=\"80\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_ViceToFin\" id=\"F_ViceToFin_di\">\r\n        <omgdi:waypoint x=\"770\" y=\"160\"/><omgdi:waypoint x=\"900\" y=\"160\"/>\r\n        <omgdi:waypoint x=\"900\" y=\"260\"/><omgdi:waypoint x=\"990\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_GM\" id=\"F_GM_di\">\r\n        <omgdi:waypoint x=\"940\" y=\"80\"/><omgdi:waypoint x=\"990\" y=\"80\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_FinMgr\" id=\"F_FinMgr_di\">\r\n        <omgdi:waypoint x=\"1050\" y=\"120\"/><omgdi:waypoint x=\"1050\" y=\"220\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Fin\" id=\"F_Fin_di\">\r\n        <omgdi:waypoint x=\"1110\" y=\"260\"/><omgdi:waypoint x=\"1160\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Pay\" id=\"F_Pay_di\">\r\n        <omgdi:waypoint x=\"1180\" y=\"285\"/><omgdi:waypoint x=\"1180\" y=\"320\"/>\r\n        <omgdi:waypoint x=\"1310\" y=\"320\"/><omgdi:waypoint x=\"1310\" y=\"300\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_NoPay\" id=\"F_NoPay_di\">\r\n        <omgdi:waypoint x=\"1180\" y=\"235\"/><omgdi:waypoint x=\"1180\" y=\"190\"/>\r\n        <omgdi:waypoint x=\"1435\" y=\"190\"/><omgdi:waypoint x=\"1435\" y=\"245\"/>\r\n      </bpmndi:BPMNEdge>\r\n      <bpmndi:BPMNEdge bpmnElement=\"F_Cash\" id=\"F_Cash_di\">\r\n        <omgdi:waypoint x=\"1370\" y=\"260\"/><omgdi:waypoint x=\"1420\" y=\"260\"/>\r\n      </bpmndi:BPMNEdge>\r\n    </bpmndi:BPMNPlane>\r\n  </bpmndi:BPMNDiagram>\r\n\r\n</definitions>',1,2107748758654619650,'312890',0,NULL,NULL,NULL,NULL,0,'000000',NULL,NULL,'2026-10-07 16:23:58',NULL,'2026-10-08 18:26:40',1,0,'travel_reimburse_approval_v2:4:312893',2,'travel_reimburse_approval_v2_2__test:6:315219'),(2107765851143888898,'travel_reimburse_approval_v2',NULL,'差旅报销导入验证','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!--\n  ============================================================================\n  差旅报销审批流 (formtable_main_9 / formId=2104243330272460802)  v2\n\n  路径:\n    小额 (<=5000)        : 部门上级 -> 财务审核 -> [付款网关] -> 出纳/归档\n    中额 (5000<x<=20000) : 部门上级 -> 分管领导 -> 财务审核 -> ...\n    大额 (>20000)        : 部门上级 -> 分管领导 -> 总经理 -> 财务经理复核 -> 财务审核 -> ...\n\n  wf: 扩展遵循导入器真实契约 (WfDefinitionServiceImpl:993-1012 / 1090-1201):\n    1. wf:operator / wf:fieldPerm / wf:timeout 必须【嵌在 wf:node 内部】\n       平行容器 wf:operators 等旧格式在有 wf:node 时会被整段跳过 -> 静默导入 0 行\n    2. 属性名: opType / objId / field / durationMin\n    3. signOrder 缺省=1(会签), actionWay 缺省=autoApprove —— 均显式书写\n    4. 节点菜单与退回白名单放<extJson>（即 ext_json.settings.*），导入器不解析其它 ext_* 元素\n  ============================================================================\n-->\n<definitions xmlns=\"http://www.omg.org/spec/BPMN/20100524/MODEL\"\n             xmlns:flowable=\"http://flowable.org/bpmn\"\n             xmlns:wf=\"http://www.springblade.org/workflow\"\n             xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\"\n             xmlns:omgdc=\"http://www.omg.org/spec/DD/20100524/DC\"\n             xmlns:omgdi=\"http://www.omg.org/spec/DD/20100524/DI\"\n             xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n             targetNamespace=\"http://www.springblade.org/workflow\"\n             xsi:schemaLocation=\"http://www.omg.org/spec/BPMN/20100524/MODEL http://www.omg.org/spec/BPMN/20100524/DI/BPMN20.xsd\">\n\n  <process id=\"travel_reimburse_approval_v2\" name=\"差旅报销审批流\" isExecutable=\"true\">\n\n    <startEvent id=\"StartEvent_1\" name=\"开始\" flowable:initiator=\"initiator\"/>\n    <sequenceFlow id=\"F_Start\" name=\"发起\" sourceRef=\"StartEvent_1\" targetRef=\"Task_Create\"/>\n\n    <userTask id=\"Task_Create\" name=\"申请填单\" flowable:assignee=\"${initiator}\" flowable:formKey=\"travelForm\">\n      <documentation>创建节点 = userTask + wf:node nodeType=0。发起时由程序立即 complete，可作为退回目标。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"0\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"17\" objId=\"\" signOrder=\"0\" bhxj=\"0\"/>\n          <wf:fieldPerm scope=\"main\" field=\"flowno\" perm=\"3\"/>\n          <wf:fieldPerm scope=\"main\" field=\"reqdate\" perm=\"3\"/>\n          <wf:fieldPerm scope=\"main\" field=\"reqman\" perm=\"3\"/>\n          <wf:fieldPerm scope=\"main\" field=\"reqdept\" perm=\"3\"/>\n          <wf:fieldPerm scope=\"main\" field=\"traveltype\" perm=\"3\"/>\n          <wf:fieldPerm scope=\"main\" field=\"eeramt\" perm=\"3\"/>\n          <wf:fieldPerm scope=\"main\" field=\"payamt\" perm=\"2\"/>\n          <wf:fieldPerm scope=\"main\" field=\"remark\" perm=\"2\"/>\n          <extJson>{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"attach\",\"print\"]},\"fieldCheck\":{\"script\":\"eeramt:required\"}}}</extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"F_Create\" name=\"提交\" sourceRef=\"Task_Create\" targetRef=\"Task_Department\"/>\n\n    <userTask id=\"Task_Department\" name=\"部门上级审批\" flowable:candidateGroups=\"dept_manager\">\n      <documentation>opType=18 创建人上级（即部门上级），依赖 blade_user.manager_id；为空会静默降级为无人可审。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"18\" objId=\"\" signOrder=\"0\" bhxj=\"0\"/>\n          <wf:fieldPerm scope=\"main\" field=\"eeramt\" perm=\"1\"/>\n          <wf:fieldPerm scope=\"main\" field=\"remark\" perm=\"1\"/>\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\n          <extJson>{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"attach\",\"opinion\",\"print\",\"urge\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_Create\"]}}}</extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"F_Dept\" name=\"部门通过\" sourceRef=\"Task_Department\" targetRef=\"Gateway_Amount\"/>\n\n    <exclusiveGateway id=\"Gateway_Amount\" name=\"金额分级\" default=\"F_Climb\">\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\n    </exclusiveGateway>\n    <sequenceFlow id=\"F_Small\" name=\"小额≤5000\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_FinReview\">\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &lt;= 5000}</conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"F_Climb\" name=\"超过5000 逐级上报(default)\" sourceRef=\"Gateway_Amount\" targetRef=\"Task_Vice\"/>\n\n    <userTask id=\"Task_Vice\" name=\"分管领导审批\" flowable:candidateGroups=\"vice_leader\">\n      <documentation>opType=2 角色（分管领导）。分管领导/总经理无专用 opType，只能用角色或岗位。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"vice_leader_role_id\" signOrder=\"0\" bhxj=\"0\"/>\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\n          <extJson>{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"attach\",\"opinion\",\"print\",\"urge\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_Department\",\"Task_Create\"]}}}</extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"F_Vice\" name=\"分管通过\" sourceRef=\"Task_Vice\" targetRef=\"Gateway_Level\"/>\n\n    <exclusiveGateway id=\"Gateway_Level\" name=\"是否需总经理\" default=\"F_ViceToFin\">\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\n    </exclusiveGateway>\n    <sequenceFlow id=\"F_Large\" name=\"大额>20000\" sourceRef=\"Gateway_Level\" targetRef=\"Task_GM\">\n      <conditionExpression xsi:type=\"tFormalExpression\">${eeramt &gt; 20000}</conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"F_ViceToFin\" name=\"中额 直达财务(default)\" sourceRef=\"Gateway_Level\" targetRef=\"Task_FinReview\"/>\n\n    <userTask id=\"Task_GM\" name=\"总经理审批\" flowable:candidateGroups=\"gm\">\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"gm_role_id\" signOrder=\"0\" bhxj=\"0\"/>\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\n          <extJson>{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"attach\",\"opinion\",\"print\",\"urge\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_Vice\",\"Task_Department\",\"Task_Create\"]}}}</extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"F_GM\" name=\"总经理通过\" sourceRef=\"Task_GM\" targetRef=\"Task_FinManager\"/>\n\n    <userTask id=\"Task_FinManager\" name=\"财务经理复核\" flowable:candidateGroups=\"fin_manager\">\n      <documentation>大额路径专用复核；同时作为财务审核节点的加签/转办目标与 exceptionHandle 兜底目标。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"fin_manager_role_id\" signOrder=\"0\" bhxj=\"0\"/>\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\n          <extJson>{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"attach\",\"opinion\",\"print\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_FinReview\",\"Task_Create\"]}}}</extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"F_FinMgr\" name=\"复核通过\" sourceRef=\"Task_FinManager\" targetRef=\"Task_FinReview\"/>\n\n    <userTask id=\"Task_FinReview\" name=\"财务审核\" flowable:candidateGroups=\"fin_review\">\n      <documentation>核心节点：按问题类型退到不同目标 = 按条件回退（引擎 reject 本身无条件）。</documentation>\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"fin_review_role_id\" signOrder=\"0\" bhxj=\"0\"/>\n          <wf:fieldPerm scope=\"main\" field=\"eeramt\" perm=\"1\"/>\n          <wf:fieldPerm scope=\"dt1\" field=\"ablebudgetamt\" perm=\"1\"/>\n          <wf:fieldPerm scope=\"dt3\" field=\"hrmbankaccount\" perm=\"1\"/>\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"2880\" actionWay=\"remind\" remindTypes=\"sys,ml\"/>\n          <extJson>{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"forward\",\"transfer\",\"sign\",\"circulate\",\"attach\",\"opinion\",\"print\",\"urge\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_Create\",\"Task_Department\",\"Task_Vice\",\"Task_GM\",\"Task_FinManager\"]},\"exceptionHandle\":{\"enabled\":true,\"way\":1,\"targetNodeKey\":\"Task_FinManager\",\"mode\":1}}}</extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"F_Fin\" name=\"财务通过\" sourceRef=\"Task_FinReview\" targetRef=\"Gateway_Pay\"/>\n\n    <exclusiveGateway id=\"Gateway_Pay\" name=\"是否需付款\" default=\"F_NoPay\">\n      <extensionElements><wf:node nodeType=\"7\"/></extensionElements>\n    </exclusiveGateway>\n    <sequenceFlow id=\"F_Pay\" name=\"需付款\" sourceRef=\"Gateway_Pay\" targetRef=\"Task_Cashier\">\n      <conditionExpression xsi:type=\"tFormalExpression\">${payamt &gt; 0}</conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id=\"F_NoPay\" name=\"无需付款(default)\" sourceRef=\"Gateway_Pay\" targetRef=\"EndEvent_Archive\"/>\n\n    <userTask id=\"Task_Cashier\" name=\"出纳付款确认\" flowable:candidateGroups=\"cashier\">\n      <extensionElements>\n        <wf:node nodeType=\"1\" signOrder=\"0\" allowReject=\"1\" autoApprove=\"0\">\n          <wf:operator opType=\"2\" objId=\"cashier_role_id\" signOrder=\"0\" bhxj=\"0\"/>\n          <wf:timeout seq=\"1\" enabled=\"1\" startType=\"1\" endType=\"1\" durationMin=\"1440\" actionWay=\"remind\" remindTypes=\"sys\"/>\n          <extJson>{\"settings\":{\"operateMenu\":{\"menus\":[\"submit\",\"save\",\"reject\",\"attach\",\"opinion\",\"print\"]},\"reject\":{\"type\":2,\"nodeKeys\":[\"Task_FinReview\",\"Task_Create\"]}}}</extJson>\n        </wf:node>\n      </extensionElements>\n    </userTask>\n    <sequenceFlow id=\"F_Cash\" name=\"付款完成\" sourceRef=\"Task_Cashier\" targetRef=\"EndEvent_Archive\"/>\n\n    <endEvent id=\"EndEvent_Archive\" name=\"归档\">\n      <extensionElements><wf:node nodeType=\"3\"/></extensionElements>\n    </endEvent>\n\n  </process>\n\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_1\">\n    <bpmndi:BPMNPlane bpmnElement=\"travel_reimburse_approval_v2\" id=\"BPMNPlane_1\">\n      <bpmndi:BPMNShape bpmnElement=\"StartEvent_1\" id=\"StartEvent_1_di\">\n        <omgdc:Bounds x=\"60\" y=\"245\" width=\"30\" height=\"30\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_Create\" id=\"Task_Create_di\">\n        <omgdc:Bounds x=\"130\" y=\"220\" width=\"120\" height=\"80\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_Department\" id=\"Task_Department_di\">\n        <omgdc:Bounds x=\"300\" y=\"220\" width=\"120\" height=\"80\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Amount\" id=\"Gateway_Amount_di\">\n        <omgdc:Bounds x=\"470\" y=\"235\" width=\"40\" height=\"50\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_Vice\" id=\"Task_Vice_di\">\n        <omgdc:Bounds x=\"560\" y=\"120\" width=\"120\" height=\"80\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Level\" id=\"Gateway_Level_di\">\n        <omgdc:Bounds x=\"730\" y=\"135\" width=\"40\" height=\"50\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_GM\" id=\"Task_GM_di\">\n        <omgdc:Bounds x=\"820\" y=\"40\" width=\"120\" height=\"80\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_FinManager\" id=\"Task_FinManager_di\">\n        <omgdc:Bounds x=\"990\" y=\"40\" width=\"120\" height=\"80\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_FinReview\" id=\"Task_FinReview_di\">\n        <omgdc:Bounds x=\"990\" y=\"220\" width=\"120\" height=\"80\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Gateway_Pay\" id=\"Gateway_Pay_di\">\n        <omgdc:Bounds x=\"1160\" y=\"235\" width=\"40\" height=\"50\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"Task_Cashier\" id=\"Task_Cashier_di\">\n        <omgdc:Bounds x=\"1250\" y=\"220\" width=\"120\" height=\"80\"/>\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape bpmnElement=\"EndEvent_Archive\" id=\"EndEvent_Archive_di\">\n        <omgdc:Bounds x=\"1420\" y=\"245\" width=\"30\" height=\"30\"/>\n      </bpmndi:BPMNShape>\n\n      <bpmndi:BPMNEdge bpmnElement=\"F_Start\" id=\"F_Start_di\">\n        <omgdi:waypoint x=\"90\" y=\"260\"/><omgdi:waypoint x=\"130\" y=\"260\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Create\" id=\"F_Create_di\">\n        <omgdi:waypoint x=\"250\" y=\"260\"/><omgdi:waypoint x=\"300\" y=\"260\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Dept\" id=\"F_Dept_di\">\n        <omgdi:waypoint x=\"420\" y=\"260\"/><omgdi:waypoint x=\"470\" y=\"260\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Small\" id=\"F_Small_di\">\n        <omgdi:waypoint x=\"490\" y=\"285\"/><omgdi:waypoint x=\"490\" y=\"340\"/>\n        <omgdi:waypoint x=\"1050\" y=\"340\"/><omgdi:waypoint x=\"1050\" y=\"300\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Climb\" id=\"F_Climb_di\">\n        <omgdi:waypoint x=\"490\" y=\"235\"/><omgdi:waypoint x=\"490\" y=\"160\"/>\n        <omgdi:waypoint x=\"560\" y=\"160\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Vice\" id=\"F_Vice_di\">\n        <omgdi:waypoint x=\"680\" y=\"160\"/><omgdi:waypoint x=\"730\" y=\"160\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Large\" id=\"F_Large_di\">\n        <omgdi:waypoint x=\"750\" y=\"135\"/><omgdi:waypoint x=\"750\" y=\"80\"/>\n        <omgdi:waypoint x=\"820\" y=\"80\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_ViceToFin\" id=\"F_ViceToFin_di\">\n        <omgdi:waypoint x=\"770\" y=\"160\"/><omgdi:waypoint x=\"900\" y=\"160\"/>\n        <omgdi:waypoint x=\"900\" y=\"260\"/><omgdi:waypoint x=\"990\" y=\"260\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_GM\" id=\"F_GM_di\">\n        <omgdi:waypoint x=\"940\" y=\"80\"/><omgdi:waypoint x=\"990\" y=\"80\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_FinMgr\" id=\"F_FinMgr_di\">\n        <omgdi:waypoint x=\"1050\" y=\"120\"/><omgdi:waypoint x=\"1050\" y=\"220\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Fin\" id=\"F_Fin_di\">\n        <omgdi:waypoint x=\"1110\" y=\"260\"/><omgdi:waypoint x=\"1160\" y=\"260\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Pay\" id=\"F_Pay_di\">\n        <omgdi:waypoint x=\"1180\" y=\"285\"/><omgdi:waypoint x=\"1180\" y=\"320\"/>\n        <omgdi:waypoint x=\"1310\" y=\"320\"/><omgdi:waypoint x=\"1310\" y=\"300\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_NoPay\" id=\"F_NoPay_di\">\n        <omgdi:waypoint x=\"1180\" y=\"235\"/><omgdi:waypoint x=\"1180\" y=\"190\"/>\n        <omgdi:waypoint x=\"1435\" y=\"190\"/><omgdi:waypoint x=\"1435\" y=\"245\"/>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge bpmnElement=\"F_Cash\" id=\"F_Cash_di\">\n        <omgdi:waypoint x=\"1370\" y=\"260\"/><omgdi:waypoint x=\"1420\" y=\"260\"/>\n      </bpmndi:BPMNEdge>\n    </bpmndi:BPMNPlane>\n  </bpmndi:BPMNDiagram>\n\n</definitions>',1,2107765851143888898,NULL,0,NULL,NULL,NULL,NULL,0,'000000',NULL,NULL,'2026-10-07 17:31:53',NULL,'2026-10-07 17:31:54',0,0,NULL,1,NULL);
